def get_icon_tile(icon_name: str, tile_color: str = "indigo", size: int = 20) -> str:
    """Wraps an inline SVG icon inside a 40x40 rounded-12px gradient tile."""
    svg = get_svg_icon(icon_name, size=size, color="#ffffff", stroke_width=2.2)
    return f"""<div class="icon-tile-gradient icon-tile-{tile_color}">{svg}</div>"""
